$code=@'
using System;
using System.Runtime.InteropServices;
using Accessibility;
public static class AccProbe {
  [StructLayout(LayoutKind.Sequential)] public struct POINT { public int x; public int y; }
  [DllImport("oleacc.dll")] public static extern int AccessibleObjectFromPoint(POINT pt, [MarshalAs(UnmanagedType.Interface)] out IAccessible acc, out object child);
  public static string Probe(int x,int y) {
    IAccessible acc; object child; int hr=AccessibleObjectFromPoint(new POINT{x=x,y=y}, out acc, out child);
    if(hr!=0 || acc==null) return "hr="+hr;
    object c = child;
    string name="", val="", role="", state="";
    try { name = Convert.ToString(acc.get_accName(c)); } catch(Exception ex){ name="nameerr:"+ex.GetType().Name; }
    try { val = Convert.ToString(acc.get_accValue(c)); } catch(Exception ex){ val="valerr:"+ex.GetType().Name; }
    try { role = Convert.ToString(acc.get_accRole(c)); } catch(Exception ex){ role="roleerr:"+ex.GetType().Name; }
    try { state = Convert.ToString(acc.get_accState(c)); } catch(Exception ex){ state="stateerr:"+ex.GetType().Name; }
    return $"child={child} name={name} value={val} role={role} state={state} type={acc.GetType().FullName}";
  }
  public static string SetVal(int x,int y,string v) {
    IAccessible acc; object child; int hr=AccessibleObjectFromPoint(new POINT{x=x,y=y}, out acc, out child);
    if(hr!=0 || acc==null) return "hr="+hr;
    try { acc.set_accValue(child, v); return "ok"; } catch(Exception ex){ return ex.ToString(); }
  }
}
