function CType($t){New-Object System.Windows.Automation.PropertyCondition([System.Windows.Automation.AutomationElement]::ControlTypeProperty,$t)}
function FindName($r,$n){$r.FindFirst([System.Windows.Automation.TreeScope]::Descendants,(CName $n))}
function Invoke($e){try{$e.GetCurrentPattern([System.Windows.Automation.InvokePattern]::Pattern).Invoke()}catch{try{$e.GetCurrentPattern([System.Windows.Automation.SelectionItemPattern]::Pattern).Select()}catch{throw}}}
$p=Start-Process 'C:\Program Files\Microsoft Office\root\Office16\EXCEL.EXE' -PassThru; Start-Sleep 8
