*** Begin Patch
*** Add File: Notepad-Gui-Test.ps1
+param(
+    [string]$BaseOutputDirectory = (Join-Path $PSScriptRoot "notepad-gui-test-runs"),
+    [switch]$KeepNotepadOpen
+)
+
+Set-StrictMode -Version 2.0
+$ErrorActionPreference = "Stop"
+
+Add-Type -AssemblyName UIAutomationClient
+Add-Type -AssemblyName UIAutomationTypes
+Add-Type -AssemblyName System.Windows.Forms
+Add-Type -AssemblyName System.Drawing
+Add-Type -TypeDefinition @"
+using System;
+using System.Runtime.InteropServices;
+
+public static class NativeInput {
+    [DllImport("user32.dll")] public static extern bool SetForegroundWindow(IntPtr hWnd);
+    [DllImport("user32.dll")] public static extern bool ShowWindow(IntPtr hWnd, int nCmdShow);
+    [DllImport("user32.dll")] public static extern bool SetCursorPos(int X, int Y);
+    [DllImport("user32.dll")] public static extern void mouse_event(uint dwFlags, uint dx, uint dy, uint dwData, UIntPtr dwExtraInfo);
+}
+"@
+
+$TextLine1 = "Notepad GUI Test"
+$TextLine2 = "This file tests creating, saving, reopening, and printing in Notepad."
+$ExpectedText = "$TextLine1`r`n$TextLine2"
+
+$RunId = Get-Date -Format "yyyyMMdd-HHmmss"
+$RunDirectory = Join-Path $BaseOutputDirectory $RunId
+New-Item -ItemType Directory -Path $RunDirectory -Force | Out-Null
+$TxtPath = Join-Path $RunDirectory "NotepadTest.txt"
+$PdfPath = Join-Path $RunDirectory "NotepadTest.pdf"
+$ResultPath = Join-Path $RunDirectory "results.json"
+$EvidencePath = Join-Path $RunDirectory "evidence.log"
+
+$Results = New-Object System.Collections.Generic.List[object]
+$NotepadProcess = $null
+
+function Write-Evidence {
+    param([string]$Message)
+    $line = "{0} {1}" -f (Get-Date -Format "o"), $Message
+    Add-Content -LiteralPath $EvidencePath -Value $line
+}
+
+function Add-StepResult {
+    param(
+        [string]$Step,
+        [bool]$Passed,
+        [string]$Details
+    )
+    $Results.Add([pscustomobject]@{
+        step = $Step
+        status = if ($Passed) { "Passed" } else { "Failed" }
+        details = $Details
+        timestamp = (Get-Date -Format "o")
+    }) | Out-Null
+    Write-Evidence "$Step - $(if ($Passed) { 'Passed' } else { 'Failed' }): $Details"
+    if (-not $Passed) {
+        throw "$Step failed: $Details"
+    }
+}
+
+function Save-Results {
+    $Results | ConvertTo-Json -Depth 5 | Set-Content -LiteralPath $ResultPath -Encoding UTF8
+}
+
+function Get-WindowForProcess {
+    param(
+        [int]$ProcessId,
+        [int]$TimeoutSeconds = 20
+    )
+    $root = [System.Windows.Automation.AutomationElement]::RootElement
+    $condition = New-Object System.Windows.Automation.PropertyCondition(
+        [System.Windows.Automation.AutomationElement]::ProcessIdProperty,
+        $ProcessId
+    )
+    $deadline = (Get-Date).AddSeconds($TimeoutSeconds)
+    do {
+        $window = $root.FindFirst([System.Windows.Automation.TreeScope]::Children, $condition)
+        if ($window) { return $window }
+        Start-Sleep -Milliseconds 250
+    } while ((Get-Date) -lt $deadline)
+    throw "Timed out waiting for Notepad window."
+}
+
+function Find-Element {
+    param(
+        [System.Windows.Automation.AutomationElement]$Root,
+        [string]$Name,
+        [System.Windows.Automation.ControlType]$ControlType,
+        [int]$TimeoutSeconds = 10
+    )
+    $conditions = @(
+        (New-Object System.Windows.Automation.PropertyCondition([System.Windows.Automation.AutomationElement]::NameProperty, $Name)),
+        (New-Object System.Windows.Automation.PropertyCondition([System.Windows.Automation.AutomationElement]::ControlTypeProperty, $ControlType))
+    )
+    $condition = New-Object System.Windows.Automation.AndCondition($conditions)
+    $deadline = (Get-Date).AddSeconds($TimeoutSeconds)
+    do {
+        try {
+            $element = $Root.FindFirst([System.Windows.Automation.TreeScope]::Descendants, $condition)
+            if ($element) { return $element }
+        } catch {}
+        Start-Sleep -Milliseconds 200
+    } while ((Get-Date) -lt $deadline)
+    return $null
+}
+
+function Find-ElementByAutomationId {
+    param(
+        [System.Windows.Automation.AutomationElement]$Root,
+        [string]$AutomationId,
+        [System.Windows.Automation.ControlType]$ControlType,
+        [int]$TimeoutSeconds = 10
+    )
+    $conditions = @(
+        (New-Object System.Windows.Automation.PropertyCondition([System.Windows.Automation.AutomationElement]::AutomationIdProperty, $AutomationId)),
+        (New-Object System.Windows.Automation.PropertyCondition([System.Windows.Automation.AutomationElement]::ControlTypeProperty, $ControlType))
+    )
+    $condition = New-Object System.Windows.Automation.AndCondition($conditions)
+    $deadline = (Get-Date).AddSeconds($TimeoutSeconds)
+    do {
+        try {
+            $element = $Root.FindFirst([System.Windows.Automation.TreeScope]::Descendants, $condition)
+            if ($element) { return $element }
+        } catch {}
+        Start-Sleep -Milliseconds 200
+    } while ((Get-Date) -lt $deadline)
+    return $null
+}
+
+function Click-Element {
+    param([System.Windows.Automation.AutomationElement]$Element)
+    if (-not $Element) { throw "Cannot click a null element." }
+    $rect = $Element.Current.BoundingRectangle
+    if ($rect.Width -le 0 -or $rect.Height -le 0) { throw "Element '$($Element.Current.Name)' has no clickable bounds." }
+    $x = [int]($rect.Left + ($rect.Width / 2))
+    $y = [int]($rect.Top + ($rect.Height / 2))
+    [NativeInput]::SetCursorPos($x, $y) | Out-Null
+    Start-Sleep -Milliseconds 100
+    [NativeInput]::mouse_event(0x0002, 0, 0, 0, [UIntPtr]::Zero)
+    Start-Sleep -Milliseconds 50
+    [NativeInput]::mouse_event(0x0004, 0, 0, 0, [UIntPtr]::Zero)
+    Start-Sleep -Milliseconds 250
+}
+
+function Invoke-Element {
+    param([System.Windows.Automation.AutomationElement]$Element)
+    if (-not $Element) { throw "Cannot invoke a null element." }
+    try {
+        $pattern = $Element.GetCurrentPattern([System.Windows.Automation.InvokePattern]::Pattern)
+        $pattern.Invoke()
+        Start-Sleep -Milliseconds 400
+    } catch {
+        Click-Element $Element
+    }
+}
+
+function Focus-Window {
+    param([System.Windows.Automation.AutomationElement]$Window)
+    [NativeInput]::ShowWindow([IntPtr]$Window.Current.NativeWindowHandle, 9) | Out-Null
+    [NativeInput]::SetForegroundWindow([IntPtr]$Window.Current.NativeWindowHandle) | Out-Null
+    Start-Sleep -Milliseconds 300
+}
+
+function Send-TextAsUser {
+    param([string]$Text)
+    foreach ($char in $Text.ToCharArray()) {
+        if ($char -eq "`r" -or $char -eq "`n") {
+            [System.Windows.Forms.SendKeys]::SendWait("{ENTER}")
+        } else {
+            [System.Windows.Forms.SendKeys]::SendWait([System.Windows.Forms.SendKeys]::Escape([string]$char))
+        }
+        Start-Sleep -Milliseconds 12
+    }
+}
+
+function Get-DocumentText {
+    param([System.Windows.Automation.AutomationElement]$Window)
+    $doc = Find-Element $Window "Text editor" ([System.Windows.Automation.ControlType]::Document) 10
+    if (-not $doc) { throw "Could not find Notepad text editor." }
+    try {
+        $textPattern = $doc.GetCurrentPattern([System.Windows.Automation.TextPattern]::Pattern)
+        return $textPattern.DocumentRange.GetText(-1).TrimEnd("`r", "`n")
+    } catch {
+        try {
+            $valuePattern = $doc.GetCurrentPattern([System.Windows.Automation.ValuePattern]::Pattern)
+            return $valuePattern.Current.Value.TrimEnd("`r", "`n")
+        } catch {
+            throw "Could not read text from Notepad editor."
+        }
+    }
+}
+
+function Open-FileMenuItem {
+    param(
+        [System.Windows.Automation.AutomationElement]$Window,
+        [string]$ItemName
+    )
+    Focus-Window $Window
+    $file = Find-ElementByAutomationId $Window "File" ([System.Windows.Automation.ControlType]::MenuItem) 10
+    if (-not $file) { $file = Find-Element $Window "File" ([System.Windows.Automation.ControlType]::MenuItem) 10 }
+    if (-not $file) { throw "Could not find File menu." }
+    try {
+        $expand = $file.GetCurrentPattern([System.Windows.Automation.ExpandCollapsePattern]::Pattern)
+        $expand.Expand()
+    } catch {
+        Click-Element $file
+    }
+    Start-Sleep -Milliseconds 500
+    $item = Find-Element $Window $ItemName ([System.Windows.Automation.ControlType]::MenuItem) 10
+    if (-not $item) { throw "Could not find File > $ItemName." }
+    Invoke-Element $item
+    Start-Sleep -Milliseconds 700
+}
+
+function Wait-DesktopWindow {
+    param(
+        [string[]]$Names,
+        [int]$TimeoutSeconds = 15
+    )
+    $root = [System.Windows.Automation.AutomationElement]::RootElement
+    $deadline = (Get-Date).AddSeconds($TimeoutSeconds)
+    do {
+        foreach ($name in $Names) {
+            $condition = New-Object System.Windows.Automation.PropertyCondition(
+                [System.Windows.Automation.AutomationElement]::NameProperty,
+                $name
+            )
+            $window = $root.FindFirst([System.Windows.Automation.TreeScope]::Children, $condition)
+            if ($window) { return $window }
+        }
+        Start-Sleep -Milliseconds 250
+    } while ((Get-Date) -lt $deadline)
+    return $null
+}
+
+function Set-DialogFileNameAndConfirm {
+    param(
+        [System.Windows.Automation.AutomationElement]$Dialog,
+        [string]$Path,
+        [string]$ButtonName
+    )
+    Focus-Window $Dialog
+    $fileName = Find-Element $Dialog "File name:" ([System.Windows.Automation.ControlType]::Edit) 10
+    if (-not $fileName) { $fileName = Find-ElementByAutomationId $Dialog "1001" ([System.Windows.Automation.ControlType]::Edit) 5 }
+    if (-not $fileName) { throw "Could not find the File name field in '$($Dialog.Current.Name)'." }
+    $fileName.SetFocus()
+    Start-Sleep -Milliseconds 150
+    try {
+        $value = $fileName.GetCurrentPattern([System.Windows.Automation.ValuePattern]::Pattern)
+        $value.SetValue($Path)
+    } catch {
+        Send-TextAsUser $Path
+    }
+    Start-Sleep -Milliseconds 300
+    $button = Find-Element $Dialog $ButtonName ([System.Windows.Automation.ControlType]::Button) 10
+    if (-not $button) { throw "Could not find the '$ButtonName' button in '$($Dialog.Current.Name)'." }
+    Invoke-Element $button
+    Start-Sleep -Seconds 1
+}
+
+function Dismiss-NotepadPopups {
+    param([System.Windows.Automation.AutomationElement]$Window)
+    foreach ($name in @("OK", "Got it")) {
+        $button = Find-Element $Window $name ([System.Windows.Automation.ControlType]::Button) 2
+        if ($button) {
+            Invoke-Element $button
+            Start-Sleep -Milliseconds 500
+        }
+    }
+}
+
+function Save-WindowScreenshot {
+    param(
+        [System.Windows.Automation.AutomationElement]$Window,
+        [string]$Name
+    )
+    $rect = $Window.Current.BoundingRectangle
+    if ($rect.Width -le 0 -or $rect.Height -le 0) { return }
+    $file = Join-Path $RunDirectory $Name
+    $bitmap = New-Object System.Drawing.Bitmap ([int]$rect.Width), ([int]$rect.Height)
+    $graphics = [System.Drawing.Graphics]::FromImage($bitmap)
+    try {
+        $graphics.CopyFromScreen([int]$rect.Left, [int]$rect.Top, 0, 0, $bitmap.Size)
+        $bitmap.Save($file, [System.Drawing.Imaging.ImageFormat]::Png)
+    } finally {
+        $graphics.Dispose()
+        $bitmap.Dispose()
+    }
+    Write-Evidence "Saved screenshot: $file"
+}
+
+function Select-PrinterAndPrintToPdf {
+    param([string]$OutputPdf)
+    $printWindow = Wait-DesktopWindow @("Print") 20
+    if (-not $printWindow) { throw "Print dialog did not appear." }
+    Focus-Window $printWindow
+
+    $printer = Find-Element $printWindow "Microsoft Print to PDF" ([System.Windows.Automation.ControlType]::Text) 10
+    if (-not $printer) { $printer = Find-Element $printWindow "Microsoft Print to PDF" ([System.Windows.Automation.ControlType]::ListItem) 5 }
+    if (-not $printer) { $printer = Find-Element $printWindow "Microsoft Print to PDF" ([System.Windows.Automation.ControlType]::DataItem) 5 }
+    if (-not $printer) { throw "Could not find Microsoft Print to PDF in the Print dialog." }
+    Click-Element $printer
+
+    $printButton = Find-Element $printWindow "Print" ([System.Windows.Automation.ControlType]::Button) 10
+    if (-not $printButton) { throw "Could not find Print button." }
+    Invoke-Element $printButton
+
+    $saveOutput = Wait-DesktopWindow @("Save Print Output As", "Save As") 20
+    if (-not $saveOutput) { throw "Save Print Output As dialog did not appear." }
+    Set-DialogFileNameAndConfirm $saveOutput $OutputPdf "Save"
+}
+
+function Inflate-PdfStream {
+    param([byte[]]$Bytes)
+    foreach ($candidate in @($Bytes, $(if ($Bytes.Length -gt 6) { $Bytes[2..($Bytes.Length -5)] } else { $Bytes }))) {
+        try {
+            $input = New-Object System.IO.MemoryStream(,$candidate)
+            $deflate = New-Object System.IO.Compression.DeflateStream($input, [System.IO.Compression.CompressionMode]::Decompress)
+            $output = New-Object System.IO.MemoryStream
+            $deflate.CopyTo($output)
+            $deflate.Dispose()
+            $input.Dispose()
+            return $output.ToArray()
+        } catch {}
+    }
+    return $Bytes
+}
+
+function Convert-PdfTextBytesToString {
+    param([byte[]]$Bytes)
+    $latin = [System.Text.Encoding]::GetEncoding(28591).GetString($Bytes)
+    $utf16 = ""
+    try { $utf16 = [System.Text.Encoding]::BigEndianUnicode.GetString($Bytes) } catch {}
+    return "$latin`n$utf16"
+}
+
+function Get-PdfSearchText {
+    param([string]$Path)
+    $bytes = [System.IO.File]::ReadAllBytes($Path)
+    $all = New-Object System.Collections.Generic.List[byte[]]
+    $all.Add($bytes)
+    $latin = [System.Text.Encoding]::GetEncoding(28591).GetString($bytes)
+    $matches = [regex]::Matches($latin, "stream\r?\n(?<data>.*?)\r?\nendstream", [System.Text.RegularExpressions.RegexOptions]::Singleline)
+    foreach ($match in $matches) {
+        $dataText = $match.Groups["data"].Value
+        $dataBytes = [System.Text.Encoding]::GetEncoding(28591).GetBytes($dataText)
+        $all.Add((Inflate-PdfStream $dataBytes))
+    }
+    $pieces = foreach ($part in $all) { Convert-PdfTextBytesToString $part }
+    return ($pieces -join "`n")
+}
+
+try {
+    Write-Evidence "Run folder: $RunDirectory"
+    $NotepadProcess = Start-Process -FilePath "notepad.exe" -ArgumentList "/new" -PassThru
+    $window = Get-WindowForProcess -ProcessId $NotepadProcess.Id -TimeoutSeconds 20
+    Focus-Window $window
+    Dismiss-NotepadPopups $window
+    Open-FileMenuItem $window "New tab"
+    $window = Get-WindowForProcess -ProcessId $NotepadProcess.Id -TimeoutSeconds 10
+    Focus-Window $window
+    $doc = Find-Element $window "Text editor" ([System.Windows.Automation.ControlType]::Document) 10
+    if (-not $doc) { throw "Could not find blank editing area." }
+    $doc.SetFocus()
+    $blank = (Get-DocumentText $window)
+    Save-WindowScreenshot $window "01-open-blank.png"
+    Add-StepResult "Open Notepad" ([string]::IsNullOrWhiteSpace($blank)) "Notepad opened with a blank editing area."
+
+    $doc.SetFocus()
+    Send-TextAsUser $ExpectedText
+    Start-Sleep -Milliseconds 500
+    $entered = (Get-DocumentText $window).Replace("`r`n", "`n").Replace("`r", "`n")
+    $expectedNormalized = $ExpectedText.Replace("`r`n", "`n")
+    Save-WindowScreenshot $window "02-created-text.png"
+    Add-StepResult "Create Test Text File" ($entered -eq $expectedNormalized) "The editing area contains both exact lines."
+
+    Open-FileMenuItem $window "Save as"
+    $saveDialog = Wait-DesktopWindow @("Save As") 20
+    if (-not $saveDialog) { throw "Save As dialog did not appear." }
+    Set-DialogFileNameAndConfirm $saveDialog $TxtPath "Save"
+    Start-Sleep -Seconds 2
+    $window = Get-WindowForProcess -ProcessId $NotepadProcess.Id -TimeoutSeconds 10
+    $titleSaved = $window.Current.Name
+    Save-WindowScreenshot $window "03-saved-file.png"
+    $txtSavedOk = (Test-Path -LiteralPath $TxtPath) -and ((Get-Item -LiteralPath $TxtPath).Length -gt 0) -and ($titleSaved -like "*NotepadTest.txt*")
+    Add-StepResult "Save Test Text File" $txtSavedOk "Saved '$TxtPath'; Notepad title is '$titleSaved'."
+
+    Open-FileMenuItem $window "Close tab"
+    Start-Sleep -Seconds 1
+    if ($NotepadProcess.HasExited) {
+        $NotepadProcess = Start-Process -FilePath "notepad.exe" -ArgumentList "/new" -PassThru
+        $window = Get-WindowForProcess -ProcessId $NotepadProcess.Id -TimeoutSeconds 20
+        Dismiss-NotepadPopups $window
+    } else {
+        $window = Get-WindowForProcess -ProcessId $NotepadProcess.Id -TimeoutSeconds 10
+    }
+    Open-FileMenuItem $window "Open"
+    $openDialog = Wait-DesktopWindow @("Open") 20
+    if (-not $openDialog) { throw "Open dialog did not appear." }
+    Set-DialogFileNameAndConfirm $openDialog $TxtPath "Open"
+    Start-Sleep -Seconds 2
+    $window = Get-WindowForProcess -ProcessId $NotepadProcess.Id -TimeoutSeconds 10
+    $reopened = (Get-DocumentText $window).Replace("`r`n", "`n").Replace("`r", "`n")
+    $fileText = (Get-Content -LiteralPath $TxtPath -Raw).Replace("`r`n", "`n").Replace("`r", "`n").TrimEnd("`n")
+    Save-WindowScreenshot $window "04-reopened-file.png"
+    Add-StepResult "Open Created Text File" (($reopened -eq $expectedNormalized) -and ($fileText -eq $expectedNormalized) -and ($window.Current.Name -like "*NotepadTest.txt*")) "Reopened text matches the saved file at '$TxtPath'."
+
+    Open-FileMenuItem $window "Print"
+    Select-PrinterAndPrintToPdf $PdfPath
+    $deadline = (Get-Date).AddSeconds(30)
+    do {
+        Start-Sleep -Milliseconds 500
+    } while ((-not (Test-Path -LiteralPath $PdfPath)) -and (Get-Date) -lt $deadline)
+    if (-not (Test-Path -LiteralPath $PdfPath)) { throw "PDF was not created." }
+    Start-Sleep -Seconds 2
+    $pdfItem = Get-Item -LiteralPath $PdfPath
+    $pdfBytes = [System.IO.File]::ReadAllBytes($PdfPath)
+    $hasHeader = $pdfBytes.Length -gt 5 -and ([System.Text.Encoding]::ASCII.GetString($pdfBytes, 0, 5) -eq "%PDF-")
+    $pdfText = Get-PdfSearchText $PdfPath
+    $pdfContainsText = ($pdfText -like "*$TextLine1*") -and ($pdfText -like "*$TextLine2*")
+    Add-StepResult "Print Test Text File" ($pdfItem.Length -gt 0 -and $hasHeader -and $pdfContainsText) "PDF saved to '$PdfPath', opens as a PDF header, and contains both expected lines."
+}
+finally {
+    Save-Results
+    if ($NotepadProcess -and -not $NotepadProcess.HasExited -and -not $KeepNotepadOpen) {
+        try {
+            $window = Get-WindowForProcess -ProcessId $NotepadProcess.Id -TimeoutSeconds 3
+            $closeButton = Find-Element $window "Close" ([System.Windows.Automation.ControlType]::Button) 3
+            if ($closeButton) { Invoke-Element $closeButton } else { $NotepadProcess.CloseMainWindow() | Out-Null }
+            Start-Sleep -Seconds 2
+            if (-not $NotepadProcess.HasExited) { $NotepadProcess.Kill() }
+        } catch {
+            try { if (-not $NotepadProcess.HasExited) { $NotepadProcess.Kill() } } catch {}
+        }
+    }
+}
+
+$passedCount = @($Results | Where-Object { $_.status -eq "Passed" }).Count
+Write-Host "Run directory: $RunDirectory"
+Write-Host "Results: $passedCount / 5 Passed"
+Write-Host "Results file: $ResultPath"
+if ($passedCount -ne 5) {
+    exit 1
+}
*** End Patch

call.command:
Get-Process Notepad -ErrorAction SilentlyContinue | Stop-Process -Force; Start-Sleep -Milliseconds 800; Add-Type -AssemblyName UIAutomationClient; Add-Type -AssemblyName UIAutomationTypes; Add-Type @'
using System;
using System.Runtime.InteropServices;
public static class NativeClick {
 [DllImport("user32.dll")] public static extern bool SetCursorPos(int X, int Y);
 [DllImport("user32.dll")] public static extern void mouse_event(uint dwFlags, uint dx, uint dy, uint dwData, UIntPtr dwExtraInfo);
 [DllImport("user32.dll")] public static extern bool SetForegroundWindow(IntPtr hWnd);
 public const uint LEFTDOWN=0x0002; public const uint LEFTUP=0x0004;
