+Add-Type @"
+using System;
+using System.Runtime.InteropServices;
+
+public static class GuiNative {
+    [DllImport("user32.dll")] public static extern bool SetCursorPos(int X, int Y);
+    [DllImport("user32.dll")] public static extern void mouse_event(uint dwFlags, uint dx, uint dy, uint dwData, UIntPtr dwExtraInfo);
+    [DllImport("user32.dll")] public static extern bool SetForegroundWindow(IntPtr hWnd);
+    [DllImport("user32.dll")] public static extern bool ShowWindow(IntPtr hWnd, int nCmdShow);
+    [DllImport("user32.dll")] public static extern uint SendInput(uint nInputs, INPUT[] pInputs, int cbSize);
+
+    public const int SW_RESTORE = 9;
+    public const uint MOUSEEVENTF_LEFTDOWN = 0x0002;
+    public const uint MOUSEEVENTF_LEFTUP = 0x0004;
+    public const int INPUT_KEYBOARD = 1;
+    public const uint KEYEVENTF_KEYUP = 0x0002;
+    public const uint KEYEVENTF_UNICODE = 0x0004;
+
+    [StructLayout(LayoutKind.Sequential)]
+    public struct INPUT {
+        public int type;
+        public InputUnion U;
+    }
+
+    [StructLayout(LayoutKind.Explicit)]
+    public struct InputUnion {
+        [FieldOffset(0)] public KEYBDINPUT ki;
+    }
+
+    [StructLayout(LayoutKind.Sequential)]
+    public struct KEYBDINPUT {
+        public ushort wVk;
+        public ushort wScan;
+        public uint dwFlags;
+        public uint time;
+        public UIntPtr dwExtraInfo;
+    }
+
+    public static void Click(int x, int y) {
+        SetCursorPos(x, y);
+        System.Threading.Thread.Sleep(120);
+        mouse_event(MOUSEEVENTF_LEFTDOWN, 0, 0, 0, UIntPtr.Zero);
+        System.Threading.Thread.Sleep(80);
+        mouse_event(MOUSEEVENTF_LEFTUP, 0, 0, 0, UIntPtr.Zero);
+        System.Threading.Thread.Sleep(160);
+    }
+
+    public static void TypeText(string text) {
+        foreach (char ch in text) {
+            INPUT[] inputs = new INPUT[2];
+            inputs[0].type = INPUT_KEYBOARD;
+            inputs[0].U.ki.wVk = 0;
+            inputs[0].U.ki.wScan = ch;
+            inputs[0].U.ki.dwFlags = KEYEVENTF_UNICODE;
+            inputs[1].type = INPUT_KEYBOARD;
+            inputs[1].U.ki.wVk = 0;
+            inputs[1].U.ki.wScan = ch;
+            inputs[1].U.ki.dwFlags = KEYEVENTF_UNICODE | KEYEVENTF_KEYUP;
+            SendInput(2, inputs, Marshal.SizeOf(typeof(INPUT)));
+            System.Threading.Thread.Sleep(8);
+        }
+    }
+}
+"@
+
+$ExpectedLines = @(
+    "Notepad GUI Test",
+    "This file tests creating, saving, reopening, and printing in Notepad."
+)
+$ExpectedText = ($ExpectedLines -join "`r`n")
+
+$RunId = Get-Date -Format "yyyyMMdd-HHmmss"
+$RunDir = Join-Path $RunRoot $RunId
+$EvidenceDir = Join-Path $RunDir "evidence"
+$TextPath = Join-Path $RunDir "NotepadTest.txt"
+$PdfPath = Join-Path $RunDir "NotepadTest.pdf"
+$ResultsPath = Join-Path $RunDir "results.json"
+$TranscriptPath = Join-Path $RunDir "run.log"
+
+New-Item -ItemType Directory -Path $EvidenceDir -Force | Out-Null
+Start-Transcript -Path $TranscriptPath -Force | Out-Null
+
+$Results = [System.Collections.Generic.List[object]]::new()
+$StartedProcesses = @()
+
+function Add-Result {
+    param(
+        [string]$Step,
+        [string]$Status,
+        [string]$Details,
+        [string[]]$Evidence = @()
+    )
+    $item = [pscustomobject]@{
+        step = $Step
+        status = $Status
+        details = $Details
+        evidence = $Evidence
+        time = (Get-Date).ToString("o")
+    }
+    $Results.Add($item)
+    Write-Host ("{0}: {1} - {2}" -f $Status, $Step, $Details)
+}
+
+function Save-Screenshot {
+    param([string]$Name)
+    $path = Join-Path $EvidenceDir ($Name + ".png")
+    $bounds = [System.Windows.Forms.Screen]::PrimaryScreen.Bounds
+    $bitmap = [System.Drawing.Bitmap]::new($bounds.Width, $bounds.Height)
+    $graphics = [System.Drawing.Graphics]::FromImage($bitmap)
+    try {
+        $graphics.CopyFromScreen($bounds.Location, [System.Drawing.Point]::Empty, $bounds.Size)
+        $bitmap.Save($path, [System.Drawing.Imaging.ImageFormat]::Png)
+    }
+    finally {
+        $graphics.Dispose()
+        $bitmap.Dispose()
+    }
+    return $path
+}
+
+function Wait-Until {
+    param(
+        [scriptblock]$Condition,
+        [int]$Seconds = $TimeoutSeconds,
+        [string]$Message = "Timed out waiting for condition."
+    )
+    $deadline = (Get-Date).AddSeconds($Seconds)
+    $lastError = $null
+    while ((Get-Date) -lt $deadline) {
+        try {
+            $value = & $Condition
+            if ($value) { return $value }
+        }
+        catch {
+            $lastError = $_
+        }
+        Start-Sleep -Milliseconds 250
+    }
+    if ($lastError) {
+        throw "$Message Last error: $($lastError.Exception.Message)"
+    }
+    throw $Message
+}
+
+function Get-Root {
+    return [System.Windows.Automation.AutomationElement]::RootElement
+}
+
+function New-PropertyCondition {
+    param($Property, $Value)
+    return [System.Windows.Automation.PropertyCondition]::new($Property, $Value)
+}
+
+function Get-TopWindowByName {
+    param([string]$NamePattern)
+    $root = Get-Root
+    $windows = $root.FindAll([System.Windows.Automation.TreeScope]::Children, [System.Windows.Automation.Condition]::TrueCondition)
+    foreach ($window in $windows) {
+        if ($window.Current.Name -match $NamePattern) { return $window }
+    }
+    return $null
+}
+
+function Start-NotepadFresh {
+    $before = @(Get-Process Notepad -ErrorAction SilentlyContinue | Select-Object -ExpandProperty Id)
+    $proc = Start-Process notepad.exe -ArgumentList "/new" -PassThru
+    Start-Sleep -Milliseconds 900
+    $window = Wait-Until -Seconds 20 -Message "Notepad did not open." -Condition {
+        $candidates = @(Get-Process Notepad -ErrorAction SilentlyContinue | Where-Object { $_.MainWindowHandle -ne 0 -and $before -notcontains $_.Id })
+        if (-not $candidates) {
+            $candidates = @(Get-Process Notepad -ErrorAction SilentlyContinue | Where-Object { $_.MainWindowHandle -ne 0 })
+        }
+        foreach ($candidate in $candidates) {
+            $element = [System.Windows.Automation.AutomationElement]::FromHandle($candidate.MainWindowHandle)
+            if ($element) {
+                $script:StartedProcesses += $candidate.Id
+                return $element
+            }
+        }
+        return $null
+    }
+    [GuiNative]::ShowWindow([IntPtr](Get-Process -Id ($script:StartedProcesses[-1])).MainWindowHandle, [GuiNative]::SW_RESTORE) | Out-Null
+    [GuiNative]::SetForegroundWindow([IntPtr](Get-Process -Id ($script:StartedProcesses[-1])).MainWindowHandle) | Out-Null
+    Start-Sleep -Milliseconds 500
+    return $window
+}
+
+function Find-Descendant {
+    param(
+        [System.Windows.Automation.AutomationElement]$Parent,
+        [string]$Name,
+        [System.Windows.Automation.ControlType]$ControlType,
+        [string]$AutomationId
+    )
+    $all = $Parent.FindAll([System.Windows.Automation.TreeScope]::Descendants, [System.Windows.Automation.Condition]::TrueCondition)
+    foreach ($element in $all) {
+        if ($Name -and $element.Current.Name -ne $Name) { continue }
+        if ($ControlType -and $element.Current.ControlType -ne $ControlType) { continue }
+        if ($AutomationId -and $element.Current.AutomationId -ne $AutomationId) { continue }
+        return $element
+    }
+    return $null
+}
+
+function Find-DescendantByNameRegex {
+    param(
+        [System.Windows.Automation.AutomationElement]$Parent,
+        [string]$NamePattern,
+        [System.Windows.Automation.ControlType]$ControlType
+    )
+    $all = $Parent.FindAll([System.Windows.Automation.TreeScope]::Descendants, [System.Windows.Automation.Condition]::TrueCondition)
+    foreach ($element in $all) {
+        if ($element.Current.Name -notmatch $NamePattern) { continue }
+        if ($ControlType -and $element.Current.ControlType -ne $ControlType) { continue }
+        return $element
+    }
+    return $null
+}
+
+function Click-Element {
+    param(
+        [System.Windows.Automation.AutomationElement]$Element,
+        [string]$Description = "element"
+    )
+    if (-not $Element) { throw "Cannot click missing $Description." }
+    $rect = $Element.Current.BoundingRectangle
+    if ([double]::IsInfinity($rect.Left) -or $rect.Width -le 0 -or $rect.Height -le 0) {
+        try {
+            $Element.GetCurrentPattern([System.Windows.Automation.InvokePattern]::Pattern).Invoke()
+            Start-Sleep -Milliseconds 500
+            return
+        }
+        catch {
+            throw "The $Description is not clickable and has no usable invoke pattern."
+        }
+    }
+    [GuiNative]::Click([int](($rect.Left + $rect.Right) / 2), [int](($rect.Top + $rect.Bottom) / 2))
+}
+
+function Get-Editor {
+    param([System.Windows.Automation.AutomationElement]$Window)
+    return Wait-Until -Seconds 10 -Message "Text editor was not found." -Condition {
+        Find-Descendant -Parent $Window -ControlType ([System.Windows.Automation.ControlType]::Document) -Name "Text editor"
+    }
+}
+
+function Get-EditorText {
+    param([System.Windows.Automation.AutomationElement]$Window)
+    $editor = Get-Editor -Window $Window
+    $pattern = $editor.GetCurrentPattern([System.Windows.Automation.TextPattern]::Pattern)
+    return $pattern.DocumentRange.GetText(-1).TrimEnd("`r", "`n")
+}
+
+function Click-NotepadMenuItem {
+    param(
+        [System.Windows.Automation.AutomationElement]$Window,
+        [string]$ItemName
+    )
+    $file = Wait-Until -Seconds 10 -Message "File menu was not found." -Condition {
+        Find-Descendant -Parent $Window -Name "File" -ControlType ([System.Windows.Automation.ControlType]::MenuItem)
+    }
+    Click-Element -Element $file -Description "File menu"
+    Start-Sleep -Milliseconds 500
+    $item = Wait-Until -Seconds 10 -Message "File > $ItemName was not found." -Condition {
+        Find-Descendant -Parent $Window -Name $ItemName -ControlType ([System.Windows.Automation.ControlType]::MenuItem)
+    }
+    Click-Element -Element $item -Description "File > $ItemName"
+    Start-Sleep -Milliseconds 700
+}
+
+function Wait-ForDialog {
+    param([string]$NamePattern, [int]$Seconds = $TimeoutSeconds)
+    return Wait-Until -Seconds $Seconds -Message "Dialog '$NamePattern' did not appear." -Condition {
+        Get-TopWindowByName -NamePattern $NamePattern
+    }
+}
+
+function Type-IntoFocusedField {
+    param([string]$Text)
+    Start-Sleep -Milliseconds 250
+    [GuiNative]::TypeText($Text)
+    Start-Sleep -Milliseconds 500
+}
+
+function Click-DialogButton {
+    param(
+        [System.Windows.Automation.AutomationElement]$Dialog,
+        [string]$Name,
+        [string]$AutomationId
+    )
+    $button = $null
+    if ($AutomationId) {
+        $button = Find-Descendant -Parent $Dialog -AutomationId $AutomationId
+    }
+    if (-not $button) {
+        $button = Find-Descendant -Parent $Dialog -Name $Name
+    }
+    Click-Element -Element $button -Description "dialog button $Name"
+}
+
+function Save-TextFileThroughDialog {
+    param(
+        [System.Windows.Automation.AutomationElement]$Window,
+        [string]$Path
+    )
+    Click-NotepadMenuItem -Window $Window -ItemName "Save as"
+    $dialog = Wait-ForDialog -NamePattern "^Save as$"
+    [GuiNative]::TypeText($Path)
+    Start-Sleep -Milliseconds 500
+    Click-DialogButton -Dialog $dialog -Name "Save" -AutomationId "1"
+    Wait-Until -Seconds 15 -Message "Save dialog did not close." -Condition {
+        -not (Get-TopWindowByName -NamePattern "^Save as$")
+    } | Out-Null
+}
+
+function Open-TextFileThroughDialog {
+    param(
+        [System.Windows.Automation.AutomationElement]$Window,
+        [string]$Path
+    )
+    Click-NotepadMenuItem -Window $Window -ItemName "Open"
+    $dialog = Wait-ForDialog -NamePattern "^Open$"
+    [GuiNative]::TypeText($Path)
+    Start-Sleep -Milliseconds 500
+    Click-DialogButton -Dialog $dialog -Name "Open" -AutomationId "1"
+    Wait-Until -Seconds 15 -Message "Open dialog did not close." -Condition {
+        -not (Get-TopWindowByName -NamePattern "^Open$")
+    } | Out-Null
+}
+
+function Close-CurrentTab {
+    param([System.Windows.Automation.AutomationElement]$Window)
+    $closeTab = Wait-Until -Seconds 10 -Message "Close Tab button was not found." -Condition {
+        Find-Descendant -Parent $Window -Name "Close Tab" -ControlType ([System.Windows.Automation.ControlType]::Button)
+    }
+    Click-Element -Element $closeTab -Description "Close Tab"
+    Start-Sleep -Seconds 1
+}
+
+function Print-TextFileThroughDialog {
+    param(
+        [System.Windows.Automation.AutomationElement]$Window,
+        [string]$Path
+    )
+    Click-NotepadMenuItem -Window $Window -ItemName "Print"
+    $printWindow = Wait-ForDialog -NamePattern "Notepad - Print" -Seconds 20
+    $printerCombo = Wait-Until -Seconds 10 -Message "Printer selector was not found." -Condition {
+        Find-Descendant -Parent $printWindow -AutomationId "printerSelector"
+    }
+    try {
+        $printerCombo.GetCurrentPattern([System.Windows.Automation.ExpandCollapsePattern]::Pattern).Expand()
+    }
+    catch {
+        Click-Element -Element $printerCombo -Description "Printer selector"
+    }
+    Start-Sleep -Milliseconds 800
+    $pdfPrinter = Wait-Until -Seconds 10 -Message "Microsoft Print to PDF was not found." -Condition {
+        Find-Descendant -Parent $printWindow -Name "Microsoft Print to PDF" -ControlType ([System.Windows.Automation.ControlType]::ListItem)
+    }
+    Click-Element -Element $pdfPrinter -Description "Microsoft Print to PDF printer"
+    Start-Sleep -Milliseconds 800
+    $printButton = Wait-Until -Seconds 10 -Message "Print button was not found." -Condition {
+        Find-Descendant -Parent $printWindow -AutomationId "PrintButton"
+    }
+    Click-Element -Element $printButton -Description "Print button"
+    $saveDialog = Wait-ForDialog -NamePattern "Save Print Output As|Save as" -Seconds 30
+    [GuiNative]::TypeText($Path)
+    Start-Sleep -Milliseconds 500
+    Click-DialogButton -Dialog $saveDialog -Name "Save" -AutomationId "1"
+    Wait-Until -Seconds 30 -Message "PDF was not created." -Condition {
+        Test-Path -LiteralPath $Path
+    } | Out-Null
+    Wait-Until -Seconds 30 -Message "PDF was empty." -Condition {
+        if (Test-Path -LiteralPath $Path) {
+            ((Get-Item -LiteralPath $Path).Length -gt 0)
+        }
+    } | Out-Null
+}
+
+function Test-PdfOpens {
+    param([string]$Path)
+    $bytes = [System.IO.File]::ReadAllBytes($Path)
+    $header = [System.Text.Encoding]::ASCII.GetString($bytes, 0, [Math]::Min(8, $bytes.Length))
+    return $header.StartsWith("%PDF-")
+}
+
+function Get-PdfAsciiTextEvidence {
+    param([string]$Path)
+    $bytes = [System.IO.File]::ReadAllBytes($Path)
+    $builder = [System.Text.StringBuilder]::new()
+    foreach ($byte in $bytes) {
+        if (($byte -ge 32 -and $byte -le 126) -or $byte -in 9,10,13) {
+            [void]$builder.Append([char]$byte)
+        }
+        else {
+            [void]$builder.Append(" ")
+        }
+    }
+    return $builder.ToString()
+}
+
+function Test-PdfContainsExpectedLines {
+    param([string]$Path)
+    $ascii = Get-PdfAsciiTextEvidence -Path $Path
+    $asciiPath = Join-Path $EvidenceDir "pdf-ascii-scan.txt"
+    Set-Content -LiteralPath $asciiPath -Value $ascii -Encoding UTF8
+    $hasLiteralLines = $true
+    foreach ($line in $ExpectedLines) {
+        if ($ascii -notlike "*$line*") { $hasLiteralLines = $false }
+    }
+    if ($hasLiteralLines) { return $true }
+
+    # Microsoft Print to PDF commonly stores text with simple spacing between glyphs.
+    foreach ($line in $ExpectedLines) {
+        $pattern = (($line.ToCharArray() | ForEach-Object { [regex]::Escape([string]$_) }) -join "\s*")
+        if ($ascii -notmatch $pattern) { return $false }
+    }
+    return $true
+}
+
+try {
+    $notepad = Start-NotepadFresh
+    $initialText = Get-EditorText -Window $notepad
+    $shot = Save-Screenshot -Name "01-open-notepad"
+    if ($initialText.Length -eq 0) {
+        Add-Result -Step "Open Notepad" -Status "Passed" -Details "Notepad opened with a blank editing area." -Evidence @($shot)
+    }
+    else {
+        throw "Notepad did not open blank. Current text: $initialText"
+    }
+
+    $editor = Get-Editor -Window $notepad
+    Click-Element -Element $editor -Description "text editor"
+    Type-IntoFocusedField -Text $ExpectedText
+    $typedText = Get-EditorText -Window $notepad
+    $shot = Save-Screenshot -Name "02-created-text"
+    if ($typedText -eq $ExpectedText) {
+        Add-Result -Step "Create Test Text File" -Status "Passed" -Details "The editing area displays both exact lines." -Evidence @($shot)
+    }
+    else {
+        throw "Typed text did not match. Actual: $typedText"
+    }
+
+    Save-TextFileThroughDialog -Window $notepad -Path $TextPath
+    $savedText = Get-Content -LiteralPath $TextPath -Raw -Encoding UTF8
+    $titleAfterSave = (Get-Process -Id $StartedProcesses[-1]).MainWindowTitle
+    $shot = Save-Screenshot -Name "03-saved-file"
+    if ((Test-Path -LiteralPath $TextPath) -and ((Get-Item -LiteralPath $TextPath).Length -gt 0) -and ($savedText.TrimEnd("`r","`n") -eq $ExpectedText) -and ($titleAfterSave -match "NotepadTest\.txt")) {
+        Add-Result -Step "Save Test Text File" -Status "Passed" -Details "NotepadTest.txt exists, is non-empty, UTF-8 readable, and Notepad shows the saved filename." -Evidence @($TextPath, $shot)
+    }
+    else {
+        throw "Saved file verification failed. Title: $titleAfterSave"
+    }
+
+    Close-CurrentTab -Window $notepad
+    if (-not (Get-Process -Id $StartedProcesses[-1] -ErrorAction SilentlyContinue) -or (Get-Process -Id $StartedProcesses[-1] -ErrorAction SilentlyContinue).MainWindowHandle -eq 0) {
+        $notepad = Start-NotepadFresh
+    }
+    else {
+        $notepad = [System.Windows.Automation.AutomationElement]::FromHandle((Get-Process -Id $StartedProcesses[-1]).MainWindowHandle)
+    }
+    Open-TextFileThroughDialog -Window $notepad -Path $TextPath
+    Start-Sleep -Seconds 1
+    $reopenedText = Get-EditorText -Window $notepad
+    $shot = Save-Screenshot -Name "04-reopened-file"
+    if ($reopenedText -eq $ExpectedText) {
+        Add-Result -Step "Open Created Text File" -Status "Passed" -Details "The saved file reopened with both exact lines." -Evidence @($shot)
+    }
+    else {
+        throw "Reopened content did not match. Actual: $reopenedText"
+    }
+
+    Print-TextFileThroughDialog -Window $notepad -Path $PdfPath
+    $shot = Save-Screenshot -Name "05-printed-pdf"
+    if ((Test-Path -LiteralPath $PdfPath) -and (Test-PdfOpens -Path $PdfPath) -and (Test-PdfContainsExpectedLines -Path $PdfPath)) {
+        Add-Result -Step "Print Test Text File" -Status "Passed" -Details "NotepadTest.pdf exists, has a valid PDF header, and contains both complete text lines." -Evidence @($PdfPath, $shot, (Join-Path $EvidenceDir "pdf-ascii-scan.txt"))
+    }
+    else {
+        throw "PDF verification failed."
+    }
+}
+catch {
+    $shot = $null
+    try { $shot = Save-Screenshot -Name "failure" } catch {}
+    Add-Result -Step "Run" -Status "Failed" -Details $_.Exception.Message -Evidence @($shot)
+    throw
+}
+finally {
+    foreach ($id in ($StartedProcesses | Select-Object -Unique)) {
+        try {
+            $p = Get-Process -Id $id -ErrorAction SilentlyContinue
+            if ($p) { $p.CloseMainWindow() | Out-Null; Start-Sleep -Milliseconds 800 }
+            $p = Get-Process -Id $id -ErrorAction SilentlyContinue
+            if ($p) { Stop-Process -Id $id -Force -ErrorAction SilentlyContinue }
+        }
+        catch {}
+    }
+    $Results | ConvertTo-Json -Depth 5 | Set-Content -LiteralPath $ResultsPath -Encoding UTF8
+    Stop-Transcript | Out-Null
+    Write-Host "Results: $ResultsPath"
+    Write-Host "Run directory: $RunDir"
+}
+
+$failed = @($Results | Where-Object { $_.Status -ne "Passed" })
+if ($failed.Count -gt 0) {
+    exit 1
+}
+exit 0
